//
// One cell is focusable at a time; the rest carry tabindex -1. When the
// operator tabs, the manager resolves which cell key should receive focus next
// and moves the roving tabindex there. The manager keeps a reference to the
// live collection and a layout map that indexes cell traversal order.

import { buildLayoutMap, nextCell, firstCell, hasCell } from './layoutMap.js';

export function createFocusManager({ collection, getCellEl }) {
