    map: buildLayoutMap(collection),
    currentKey: null,
  };

  function snapshotMap() {
    return state.map;
  }

  function setFocus(cellKey) {
    if (state.currentKey) {
      const prev = getCellEl(state.currentKey);
      if (prev) prev.tabIndex = -1;
    }
    const el = getCellEl(cellKey);
    if (!el) return;
    el.tabIndex = 0;
    el.focus();
    state.currentKey = cellKey;
  }

  // Resolve the cell that Tab should advance to from the current cell.
  function resolveNext() {
    const map = snapshotMap();
    if (!state.currentKey || !hasCell(map, state.currentKey)) {
      return firstCell(map);
    }
    return nextCell(map, state.currentKey);
  }

  function focusInitial(cellKey) {
    setFocus(cellKey);
  }

  function advance() {
    const target = resolveNext();
    if (target) setFocus(target);
    return target;
  }

  return { focusInitial, advance, getCurrentKey: () => state.currentKey };
}
