// Layout map: a flat, keyboard-traversable index over the board's cells.
//
// Given a collection snapshot, produce an ordered list of cell keys in reading
// order (across each row, then down to the next row) plus lookups between a
// cell key and its position in that traversal. Cell keys are `${rowKey}:${col}`.

export function buildLayoutMap(collection) {
  const cells = [];
  const posOfCell = new Map();
  for (const row of collection.rows) {
    for (const col of collection.columns) {
      const cellKey = `${row.key}:${col}`;
      posOfCell.set(cellKey, cells.length);
      cells.push(cellKey);
    }
  }
  return { cells, posOfCell };
}

export function nextCell(map, cellKey) {
  const pos = map.posOfCell.get(cellKey);
  if (pos == null) return null;
  const at = pos + 1;
  return at < map.cells.length ? map.cells[at] : null;
}

export function firstCell(map) {
  return map.cells.length ? map.cells[0] : null;
}

export function hasCell(map, cellKey) {
  return map.posOfCell.has(cellKey);
}
// Ordered collection for the fulfillment board.
//
// Rows carry a stable `key` and, for late arrivals, an `after` relation naming
// the ticket they file in behind (null files to the top). `settle` folds a set
// of arriving rows into a base ordering by honoring those relations, producing
// the top-to-bottom order the operator sees once the board stops moving.

export function makeCollection(columns) {
  return { columns: columns.slice(), rows: [] };
}

export function seedRows(collection, rows) {
  collection.rows = rows.map((r) => ({ ...r }));
